      backup_text =
        "# NIGHT GARDEN NUTRIENT TRACKER #\n\
         # A mystical soil management system for sustainable moon farming #\n\n\
         # ========================================= #\n\
         # TYPES                                     #\n\
         # ========================================= #\n\n\
         # Soil nutrients are measured 0-100 #\n\
         # N = Nitrogen, P = Phosphorus, K = Potassium #\n\
         type Soil = (\n\
         n = Int,  # Nitrogen: essential for leafy growth #\n\
         p = Int,  # Phosphorus: helps root development #\n\
         k = Int   # Potassium: overall plant health #\n\
         ) in\n\n\
         # The mystical crops of the night garden #\n\
         # Each crop has different effects on soil nutrients #\n\
         type Crop =\n\
         + Nightbeans      # Nitrogen fixer - restores N when harvested #\n\
         + Mooncorn        # Heavy feeder - depletes N significantly #\n\
         + Startomatoes    # Balanced - moderate use of all nutrients #\n\
         + TwilightClover  # Cover crop - restores N when turned under #\n\
         in\n\n\
         # A garden plot has soil state, optionally a growing crop, and season #\n\
         type Model = (\n\
         soil = Soil,\n\
         crop = +None +Some(Crop),\n\
         season = Int\n\
         ) in\n\n\
         # Actions that can be performed on a plot #\n\
         type Action =\n\
         + Plant(Crop)     # Plant a new crop (fails if plot occupied) #\n\
         + Harvest         # Harvest current crop, apply nutrient effects #\n\
         + Compost         # Add organic matter, boosts all nutrients #\n\
         + SeasonChange    # Time passes, nutrients settle #\n\
         in\n\n\
         # ========================================= #\n\
         # HELPER FUNCTIONS                          #\n\
         # ========================================= #\n\n\
         # Clamp value between 0 and 100 #\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         # ========================================= #\n\
         # INITIAL STATE                             #\n\
         # ========================================= #\n\n\
         # Balanced soil has moderate levels of all nutrients #\n\
         let balancedSoil : Soil = (n = 60, p = 60, k = 60) in\n\n\
         # A fresh plot starts with balanced soil #\n\
         let initModel : Model = (\n\
         soil = balancedSoil,\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\n\
         # ========================================= #\n\
         # NUTRIENT CALCULATIONS                     #\n\
         # ========================================= #\n\n\
         # Calculate small nutrient cost when planting #\n\
         # Different crops need different amounts to establish #\n\
         let plantingCost : (Soil, Crop) -> Soil =\n\
         fun (s, crop) ->\n\
         case crop\n\
         | Nightbeans =>\n\
         # Nightbeans establish easily, minimal cost #\n\
         (n = s.n, p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         | Mooncorn =>\n\
         # Mooncorn needs resources to start #\n\
         (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         | Startomatoes =>\n\
         # Startomatoes are standard #\n\
         (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         | TwilightClover =>\n\
         # Clover is easy to establish #\n\
         (n = s.n, p = clamp(s.p - 3), k = clamp(s.k - 3))\n\
         end\n\
         in\n\n\
         # Calculate how harvesting each crop affects soil nutrients #\n\
         # This is the main nutrient exchange in the system #\n\
         let harvestEffect : (Soil, Crop) -> Soil =\n\
         fun (s, crop) ->\n\
         case crop\n\
         | Nightbeans =>\n\
         # Nitrogen fixer: restores N, uses some P and K #\n\
         (n = clamp(s.n + 15), p = clamp(s.p - 10), k = clamp(s.k - 10))\n\
         | Mooncorn =>\n\
         # Heavy N feeder: depletes nitrogen significantly #\n\
         (n = clamp(s.n - 30), p = clamp(s.p - 10), k = clamp(s.k - 15))\n\
         | Startomatoes =>\n\
         # Balanced consumer: moderate depletion across all #\n\
         (n = clamp(s.n - 15), p = clamp(s.p - 15), k = clamp(s.k - 15))\n\
         | TwilightClover =>\n\
         # Cover crop turned under should restore nitrogen #\n\
         (n = s.n, p = clamp(s.p + 20), k = clamp(s.k - 5))\n\
         end\n\
         in\n\n\
         # Apply compost - organic matter boosts all nutrients #\n\
         let applyCompost : Soil -> Soil =\n\
         fun s ->\n\
         (n = clamp(s.n + 10), p = clamp(s.p + 10), k = clamp(s.k + 10))\n\
         in\n\n\
         # Season change causes minor nutrient settling/leaching #\n\
         let seasonSettle : Soil -> Soil =\n\
         fun s ->\n\
         (n = clamp(s.n - 3), p = clamp(s.p - 2), k = clamp(s.k - 2))\n\
         in\n\n\
         # ========================================= #\n\
         # MAIN UPDATE FUNCTION                      #\n\
         # ========================================= #\n\n\
         # Process a single action on a plot #\n\
         let update : (Model, Action) -> Model =\n\
         fun (p, action) ->\n\
         case action\n\
         | Plant(crop) =>\n\
         # Only plant if plot is empty #\n\
         case p.crop\n\
         | Some(_) => p\n\
         | None =>\n\
         (\n\
         soil = plantingCost(p.soil, crop),\n\
         crop = Some(crop),\n\
         season = p.season\n\
         )\n\
         end\n\
         | Harvest =>\n\
         # Harvest applies the crop's effect to soil #\n\
         case p.crop\n\
         | None => p\n\
         | Some(crop) =>\n\
         (\n\
         soil = harvestEffect(p.soil, crop),\n\
         crop = None,\n\
         season = p.season\n\
         )\n\
         end\n\
         | Compost =>\n\
         (\n\
         soil = applyCompost(p.soil),\n\
         crop = p.crop,\n\
         season = p.season\n\
         )\n\
         | SeasonChange =>\n\
         (\n\
         soil = seasonSettle(p.soil),\n\
         crop = p.crop,\n\
         season = p.season + 1\n\
         )\n\
         end\n\
         in\n\n\
         # Process a sequence of actions #\n\
         let farm : (Model, [Action]) -> Model =\n\
         fun (plot, actions) ->\n\
         fold_left(actions, update, plot)\n\
         in\n\n\
         # ========================================= #\n\
         # TESTS                                     #\n\
         # ========================================= #\n\n\
         hint \"planting sets the current crop\"\n\
         test\n\
         let p = update(initModel, Plant(Mooncorn)) in\n\
         p.crop == Some(Mooncorn)\n\
         end;\n\n\
         hint \"cannot plant when crop already growing\"\n\
         test\n\
         let p = farm(initModel, [Plant(Mooncorn), Plant(Startomatoes)]) in\n\
         p.crop == Some(Mooncorn)\n\
         end;\n\n\
         hint \"planting has small nutrient cost\"\n\
         test\n\
         let p = update(initModel, Plant(Startomatoes)) in\n\
         p.soil.n < initModel.soil.n\n\
         end;\n\n\
         hint \"harvesting clears the crop\"\n\
         test\n\
         let p = farm(initModel, [Plant(Mooncorn), Harvest]) in\n\
         p.crop == None\n\
         end;\n\n\
         hint \"harvesting nothing changes nothing\"\n\
         test\n\
         let p = update(initModel, Harvest) in\n\
         p == initModel\n\
         end;\n\n\
         hint \"mooncorn depletes nitrogen heavily\"\n\
         test\n\
         let p = farm(initModel, [Plant(Mooncorn), Harvest]) in\n\
         p.soil.n < initModel.soil.n - 20\n\
         end;\n\n\
         hint \"nightbeans restore nitrogen\"\n\
         test\n\
         let depleted = (\n\
         soil = (n = 30, p = 50, k = 50),\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\
         let p = farm(depleted, [Plant(Nightbeans), Harvest]) in\n\
         p.soil.n > depleted.soil.n\n\
         end;\n\n\
         hint \"twilight clover restores nitrogen significantly\"\n\
         test\n\
         let depleted = (\n\
         soil = (n = 30, p = 60, k = 60),\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\
         let p = farm(depleted, [Plant(TwilightClover), Harvest]) in\n\
         p.soil.n >= 45\n\
         end;\n\n\
         hint \"startomatoes deplete all nutrients moderately\"\n\
         test\n\
         let p = farm(initModel, [Plant(Startomatoes), Harvest]) in\n\
         p.soil.n < initModel.soil.n &&\n\
         p.soil.p < initModel.soil.p &&\n\
         p.soil.k < initModel.soil.k\n\
         end;\n\n\
         hint \"compost boosts all nutrients\"\n\
         test\n\
         let p = update(initModel, Compost) in\n\
         p.soil.n > initModel.soil.n &&\n\
         p.soil.p > initModel.soil.p &&\n\
         p.soil.k > initModel.soil.k\n\
         end;\n\n\
         hint \"compost respects maximum (100)\"\n\
         test\n\
         let rich = (soil = (n = 95, p = 95, k = 95), crop = None, season = 1) \
         in\n\
         let p = update(rich, Compost) in\n\
         p.soil.n == 100 && p.soil.p == 100 && p.soil.k == 100\n\
         end;\n\n\
         hint \"season advances counter\"\n\
         test\n\
         let p = update(initModel, SeasonChange) in\n\
         p.season == 2\n\
         end;\n\n\
         hint \"season change causes minor nutrient loss\"\n\
         test\n\
         let p = update(initModel, SeasonChange) in\n\
         p.soil.n < initModel.soil.n\n\
         end;\n\n\
         hint \"mooncorn then clover rotation restores nitrogen\"\n\
         test\n\
         let start = (soil = (n = 60, p = 60, k = 60), crop = None, season = \
         1) in\n\
         let afterMooncorn = farm(start, [Plant(Mooncorn), Harvest]) in\n\
         let afterClover = farm(afterMooncorn, [Plant(TwilightClover), \
         Harvest]) in\n\
         afterClover.soil.n > afterMooncorn.soil.n &&\n\
         afterClover.soil.n >= 40\n\
         end;\n\n\
         hint \"nutrients cannot go below 0\"\n\
         test\n\
         let poor = (soil = (n = 10, p = 10, k = 10), crop = None, season = 1) \
         in\n\
         let p = farm(poor, [Plant(Mooncorn), Harvest]) in\n\
         p.soil.n >= 0 && p.soil.p >= 0 && p.soil.k >= 0\n\
         end;\n\n\
         hint \"nutrients cannot exceed 100\"\n\
         test\n\
         let rich = (soil = (n = 90, p = 90, k = 90), crop = None, season = 1) \
         in\n\
         let p = farm(rich, [Compost, Compost, Compost]) in\n\
         p.soil.n <= 100 && p.soil.p <= 100 && p.soil.k <= 100\n\
         end;\n\n\
         # ========================================= #\n\
         # DEMO: Full growing season                 #\n\
         # ========================================= #\n\
         farm(initModel, [\n\
         Plant(Mooncorn),\n\
         SeasonChange,\n\
         Harvest,\n\
         Plant(TwilightClover),\n\
         SeasonChange,\n\
         Harvest,\n\
         Compost,\n\
         Plant(Nightbeans),\n\
         SeasonChange,\n\
         Harvest\n\
         ])\n";
      refractors = "()";
    } )
